USE health_ai_platform;

-- ============================================================
-- Real policy content for the 5 core Finance knowledge_docs
-- (v1/v2/v3 of each = 15 rows total), replacing the Faker
-- gibberish generated by generate_seed_data.py.
-- ============================================================

-- --- GL Account Mapping Guide -----------------------------
UPDATE knowledge_docs SET content = 'Each finance transaction must be coded to the correct GL account based on txn_type: PREMIUM_RECEIPT posts to the 4000-series revenue accounts, CLAIM_PAYOUT posts to the 5000-series claims expense accounts, VENDOR_PAYMENT posts to the 4500-4599 range for operating expenses by vendor category, ACCRUAL posts to the corresponding balance-sheet accrual account matching the expense it anticipates, and ADJUSTMENT posts to the same account as the original transaction being corrected, never to a generic suspense account. A transaction coded outside its expected GL range requires a documented business justification in the transaction description, since automated GL account validation will flag it for review otherwise.'
WHERE dept_id = 8 AND title = 'GL Account Mapping Guide';

UPDATE knowledge_docs SET content = 'Revision 2 narrows the VENDOR_PAYMENT range in v1 from the flat 4500-4599 block into sub-ranges by vendor category: 4500-4529 for claims-adjudication vendors (e.g. utilization review contractors), 4530-4559 for IT/technology vendors, and 4560-4599 for general operations, since the flat range was making vendor-category expense reporting difficult without manual reclassification. This revision also clarifies the ADJUSTMENT same-account rule from v1: an adjustment correcting an amount is same-account, but an adjustment correcting a GL miscoding itself is explicitly exempted from that rule and must post to the correct account, with the original incorrect posting reversed via a separate adjustment entry.'
WHERE dept_id = 8 AND title = 'GL Account Mapping Guide v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a quarterly GL mapping audit requirement: a sample of transactions in each txn_type is reviewed against this guide''s ranges every quarter, with any systematic miscoding pattern (not just individual errors) escalated to update this document rather than being silently corrected transaction-by-transaction. This revision also adds explicit accrual-reversal guidance: when an ACCRUAL is reversed upon the actual expense posting, the reversal must reference the original accrual''s txn_reference in its description field, so the accrual-to-actual relationship remains traceable in GL account activity, not just in a separate accrual tracking system.'
WHERE dept_id = 8 AND title = 'GL Account Mapping Guide v3';

-- --- Month-End Close Checklist -----------------------------
UPDATE knowledge_docs SET content = 'Month-end close must be completed within 5 business days of month end. The checklist covers: all claims adjudicated through the last day of the month are reflected in CLAIM_PAYOUT transactions (or accrued if not yet paid), all premium receipts are reconciled against the billing system''s payment records, outstanding accruals are reviewed for accuracy against actual invoices received, and any transaction dated in the closing month but entered after the close deadline is flagged for prior-period adjustment rather than silently included. The close is not considered final until a controller has reviewed and signed off on the reconciliation summary — an unsigned close is provisional and subject to revision.'
WHERE dept_id = 8 AND title = 'Month-End Close Checklist';

UPDATE knowledge_docs SET content = 'Revision 2 shortens the standard close window in v1 from 5 to 4 business days, reflecting process improvements in the claims-adjudication feed that reduced the reconciliation burden referenced in v1''s CLAIM_PAYOUT step. This revision also adds an explicit late-transaction threshold: a transaction dated in the closing month but entered more than 10 business days after month end is treated as a current-period entry rather than a prior-period adjustment, since the audit trail value of restating a closed period diminishes significantly after that window.'
WHERE dept_id = 8 AND title = 'Month-End Close Checklist v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a loss ratio calculation step to the standard checklist, cross-referencing the Loss Ratio Calculation Method: the month''s loss ratio must be calculated and compared against the trailing 3-month average as part of close, with any variance greater than 5 percentage points requiring a written explanation before the controller sign-off referenced in v1 is granted. This revision also formalizes that the controller sign-off itself must be a distinct finance_transactions-adjacent record (not just an email), so the review is auditable alongside the transactions it covers.'
WHERE dept_id = 8 AND title = 'Month-End Close Checklist v3';

-- --- Vendor Payment Approval Policy -----------------------------
UPDATE knowledge_docs SET content = 'Vendor payments under $10,000 may be approved by a finance analyst directly. Payments between $10,000 and $50,000 require controller approval. Payments above $50,000 require both controller and CFO sign-off before the VENDOR_PAYMENT transaction is posted. Recurring vendor payments under a standing contract (e.g. monthly IT services) may use a simplified approval on the first payment of each contract year rather than requiring full approval on every individual payment, provided the amount does not vary from the contracted rate. A payment to a new vendor (first payment in the finance_transactions history) always requires full approval regardless of amount.'
WHERE dept_id = 8 AND title = 'Vendor Payment Approval Policy';

UPDATE knowledge_docs SET content = 'Revision 2 raises the analyst-approval threshold in v1 from $10,000 to $15,000 and adds a documented rationale requirement at every tier: even analyst-approved payments under the threshold must record a one-line business justification in the description field, not just the vendor and amount, since audit review found justification-free small payments were harder to reconcile against budget categories after the fact. This revision also extends the new-vendor full-approval requirement from v1 to cover the first THREE payments to a new vendor, not just the first, since a single approved payment was found insufficient to establish the vendor relationship was legitimate and correctly set up.'
WHERE dept_id = 8 AND title = 'Vendor Payment Approval Policy v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a same-day expedited approval path for time-sensitive vendor payments (e.g. a service disruption risk if unpaid) that bypasses the standard multi-day approval cycle in v1 and v2, requiring only a single controller sign-off regardless of dollar amount, with CFO notification (not approval) within 24 hours after the fact. This revision also adds a vendor concentration flag: if a single vendor''s cumulative payments in a rolling 12-month period exceed a defined threshold, the next payment triggers an automatic review regardless of individual payment size, to surface vendor-dependency risk that per-payment thresholds alone would miss.'
WHERE dept_id = 8 AND title = 'Vendor Payment Approval Policy v3';

-- --- Loss Ratio Calculation Method -----------------------------
UPDATE knowledge_docs SET content = 'Loss ratio is calculated as total CLAIM_PAYOUT amount divided by total PREMIUM_RECEIPT amount for the same period, expressed as a percentage. A loss ratio above 100% means claims paid out exceeded premium collected for that period (before investment income and other revenue). Loss ratio is calculated monthly, quarterly, and on a trailing-12-month basis; the trailing-12-month figure is the primary metric reported to leadership since single-month figures can be volatile due to large individual claims. Pended or accrued-but-not-yet-paid claims are excluded from the CLAIM_PAYOUT figure used in this calculation — only actually posted CLAIM_PAYOUT transactions count, not estimated liabilities.'
WHERE dept_id = 8 AND title = 'Loss Ratio Calculation Method';

UPDATE knowledge_docs SET content = 'Revision 2 adds an incurred-but-not-reported (IBNR) adjustment to the trailing-12-month calculation in v1: rather than using only posted CLAIM_PAYOUT transactions, the trailing-12-month loss ratio also incorporates an actuarially-estimated IBNR reserve, since claims incurred late in the period are often not yet posted at calculation time and excluding them (per v1''s exclusion of accrued claims) was understating the true loss ratio for recent months specifically. The monthly and quarterly figures in v1 continue to use posted-only transactions, since IBNR estimation is less reliable at shorter time horizons.'
WHERE dept_id = 8 AND title = 'Loss Ratio Calculation Method v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a segmented loss ratio breakdown alongside the aggregate figure in v1 and v2: loss ratio is now also calculated per major service category (using the GL account mapping from the GL Account Mapping Guide) rather than only as a single company-wide figure, since an acceptable aggregate loss ratio can mask a specific category running significantly over target. This revision also clarifies that ADJUSTMENT transactions correcting a prior CLAIM_PAYOUT are included in the loss ratio calculation for the period the correction posts, not restated into the original period, consistent with the prior-period adjustment handling in the Month-End Close Checklist.'
WHERE dept_id = 8 AND title = 'Loss Ratio Calculation Method v3';

-- --- Accrual Estimation SOP -----------------------------
UPDATE knowledge_docs SET content = 'Accruals are booked for expenses incurred but not yet invoiced or paid, most commonly for claims in adjudication that have not yet resulted in a posted CLAIM_PAYOUT and for recurring vendor services billed in arrears. Accrual amounts are estimated using the most recent comparable actual (e.g. the prior month''s equivalent payment) unless a known change makes that estimate unreliable (e.g. a contract rate change), in which case the estimate must be documented with its basis in the transaction description. Every accrual must be reviewed at month-end close and either reversed against the actual invoice/payment when it posts, or re-estimated and carried forward if the actual has not yet arrived — an accrual should never simply persist unreviewed across multiple close cycles.'
WHERE dept_id = 8 AND title = 'Accrual Estimation SOP';

UPDATE knowledge_docs SET content = 'Revision 2 adds a variance threshold to the review requirement in v1: an accrual whose actual, once posted, differs from the estimate by more than 15% must be flagged for review of the estimation method itself (not just corrected via a normal ADJUSTMENT), since a large variance often indicates the "most recent comparable actual" approach in v1 is no longer appropriate for that specific accrual category. This revision also adds a maximum carry-forward limit: an accrual re-estimated and carried forward for more than 3 consecutive close cycles without resolving to an actual triggers automatic escalation to the controller, rather than v1''s general "should never simply persist" guidance being self-enforced.'
WHERE dept_id = 8 AND title = 'Accrual Estimation SOP v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a claims-specific accrual method distinct from the general "most recent comparable actual" approach in v1: claims-related accruals use a lag-triangle estimation method (based on historical patterns of how long claims take to move from incurred to paid) rather than a simple prior-period comparison, since claims accrual volume and timing patterns are more complex than typical recurring vendor accruals. This revision also formalizes that the variance threshold in v2 applies per accrual category separately (claims vs. vendor vs. other), since claims accrual variance naturally runs higher than vendor accrual variance and a single company-wide threshold was flagging normal claims variance as an estimation-method problem.'
WHERE dept_id = 8 AND title = 'Accrual Estimation SOP v3';
